package com.bank.money;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ImmutableClassDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Money m1 = new Money(new BigDecimal("50000"));
        Money m2 = m1.add(new Money(new BigDecimal("10000"))); // returns NEW instance
        log.info(() -> "m1 (unchanged) = " + m1 + ", m2 (new) = " + m2);

        List<String> items = new ArrayList<>(List.of("TRANSFER SAV2001->CUR3001"));
        TransactionRecord rec = new TransactionRecord("TXN-001", new Money(new BigDecimal("50000")), items);

        // Try to tamper via the ORIGINAL list the caller still holds:
        items.add("FAKE ENTRY");
        log.info(() -> "Caller mutated its list; record items still = " + rec.getItems());

        // Try to tamper via the getter's returned list:
        try {
            rec.getItems().add("ANOTHER FAKE");
        } catch (UnsupportedOperationException e) {
            log.info("Returned list is unmodifiable; tamper blocked");
        }
        log.info(() -> "Final record = " + rec);
    }
}

// ─── Would be Money.java in a real project ───
final class Money {                         // 1) final class: cannot be subclassed
    private final BigDecimal amount;        // 2) private final field
    Money(BigDecimal amount) { this.amount = amount; }
    BigDecimal getAmount() { return amount; }
    Money add(Money other) {                // 3) no setter; returns a NEW instance
        return new Money(amount.add(other.amount));
    }
    public String toString() { return "Rs." + amount; }
}

// ─── Would be TransactionRecord.java in a real project ───
final class TransactionRecord {
    private final String id;
    private final Money amount;
    private final List<String> items;      // mutable type -> needs defensive copy

    TransactionRecord(String id, Money amount, List<String> items) {
        this.id = id;
        this.amount = amount;
        // 4a) defensive COPY on the way IN (caller's later edits cannot affect us)
        this.items = new ArrayList<>(items);
    }

    String getId() { return id; }
    Money getAmount() { return amount; }

    // 4b) defensive copy / unmodifiable view on the way OUT
    List<String> getItems() { return Collections.unmodifiableList(items); }

    public String toString() { return id + " " + amount + " items=" + items; }
}
